        aesGcmV1.setSupply_aad_prefix(false);
        aesGcmV1.setAad_file_unique(new byte[]{20, 21, 22});
        EncryptionAlgorithm algorithm = EncryptionAlgorithm.AES_GCM_V1(aesGcmV1);

        FileDecryptionProperties properties = FileDecryptionProperties.builder()
                .withFooterKey(explicitFooterKey)
                .withKeyRetriever(keyRetriever)
                .withoutFooterSignatureVerification()
                .build();

        InternalFileDecryptor decryptor = new InternalFileDecryptor(properties);

        assertDoesNotThrow(() -> decryptor.setFileCryptoMetaData(algorithm, true, footerKeyMetaData));
        assertNotNull(decryptor.fetchFooterDecryptor(), "Footer decryptor should be initialized with explicit key");
    }
}
